<?php
/**
 * Issue #103 mixed-version contract: actual old Etna v2 serialized payloads
 * must be accepted by NEW Rigi symmetrically (no replica/owner handoff).
 *
 * The committed JSON fixture is generated by generate_legacy_v2.py from
 * immutable OLD Plugins commit 7dc9649e, running the original PHP classes.
 * No live OPNsense router or external Terraform state is used in this test.
 */
require_once __DIR__ . '/../src/opnsense/mvc/app/models/OPNsense/ApiExtensions/InterfaceSync.php';
require_once __DIR__ . '/../src/opnsense/mvc/app/models/OPNsense/ApiExtensions/HAProxySync.php';

use OPNsense\ApiExtensions\InterfaceSync;
use OPNsense\ApiExtensions\HAProxySync;

function mixedEq($expected, $actual, string $reason): void
{
    if ($expected !== $actual) {
        fwrite(STDERR, "MIXED_VERSION_FAIL: $reason\n");
        fwrite(STDERR, "expected=" . var_export($expected, true) . "\n");
        fwrite(STDERR, "actual=" . var_export($actual, true) . "\n");
        exit(1);
    }
}

function mixedUuidFactory(string $prefix): callable
{
    $i = 0;
    return static function () use (&$i, $prefix): string {
        return $prefix . (++$i);
    };
}

function mixedPolicies(array $policies): array
{
    $rows = [];
    foreach ($policies as $policy) {
        $rows[] = [
            '@attributes' => ['uuid' => 'receiver-policy-' . $policy['id']],
            'id' => $policy['id'],
            'description' => $policy['description'],
            'synchronize' => $policy['synchronize'] ? '1' : '0',
        ];
    }
    return ['shared' => ['policies' => ['policy' => $rows]]];
}

function mixedInterfaceReceiver(array $policies): array
{
    $root = mixedPolicies($policies);
    $root['assignments'] = ['assignment' => [
        ['@attributes' => ['uuid' => 'receiver-local-lan'], 'interface' => 'lan', 'policy_id' => 'core'],
        ['@attributes' => ['uuid' => 'receiver-local-ha'], 'interface' => 'core_ha_control', 'policy_id' => 'core'],
        ['@attributes' => ['uuid' => 'receiver-local-wan'], 'interface' => 'core_wan', 'policy_id' => 'core'],
    ]];
    // Old replica collection is deliberately absent: NEW Rigi must create a
    // normal policy assignment and must not depend on owner/replica metadata.
    return [
        'hasync' => [
            'pfsyncinterface' => 'core_ha_control',
            'syncitems' => 'virtualip,rules,staticroutes,interface_vlans,haproxy_objects',
        ],
        'interfaces' => [
            'lan' => ['if' => 'vtnet0', 'descr' => 'Recovery', 'enable' => '1'],
            'core_ha_control' => ['if' => 'vlan1901', 'descr' => 'HA control', 'enable' => '1'],
            'core_wan' => ['if' => 'vlan3801', 'descr' => 'WAN', 'enable' => '1'],
        ],
        'vlans' => ['vlan' => [
            ['@attributes' => ['uuid' => 'receiver-ha-vlan'], 'if' => 'vtnet1',
             'tag' => '1901', 'pcp' => '0', 'proto' => '', 'descr' => 'HA control', 'vlanif' => 'vlan1901'],
            ['@attributes' => ['uuid' => 'receiver-wan-vlan'], 'if' => 'vtnet1',
             'tag' => '3801', 'pcp' => '0', 'proto' => '', 'descr' => 'WAN', 'vlanif' => 'vlan3801'],
        ]],
        'OPNsense' => [
            'ApiExtensions' => ['InterfaceSyncPolicy' => $root],
        ],
    ];
}

function mixedHAProxyReceiver(array $policies): array
{
    $root = mixedPolicies($policies);
    $root['assignments'] = '';
    $root['haproxy_assignments'] = '';
    return [
        'hasync' => ['syncitems' => 'virtualip,rules,staticroutes,interface_vlans,haproxy_objects'],
        'OPNsense' => [
            'ApiExtensions' => ['InterfaceSyncPolicy' => $root],
            'HAProxy' => [
                'general' => ['enabled' => '1'],
                'healthchecks' => '',
                'servers' => '',
                'backends' => '',
                'frontends' => ['frontend' => [
                    '@attributes' => ['uuid' => 'local-frontend-uuid'],
                    'id' => 'local-frontend-id',
                    'enabled' => '1',
                    'name' => 'nc-sni-tls',
                    'mode' => 'tcp',
                    'customOptions' => 'use_backend nc-sni-%[req.ssl_sni,lower]',
                ]],
            ],
        ],
    ];
}

$fixture = json_decode(
    file_get_contents(__DIR__ . '/legacy_etna_v2_payload.json'),
    true,
    512,
    JSON_THROW_ON_ERROR
);
mixedEq('7dc9649eef6f86d837fa47fb1edaef6d5a790b36',
    $fixture['source_plugin_commit'], 'immutable old Etna Plugins provenance');
mixedEq('synthetic-old-etna-native-ha-payload', $fixture['fixture_type'], 'test-only fixture provenance');

$oldInterface = $fixture['interface'];
mixedEq(2, $oldInterface['version'], 'old Etna interface payload v2');
mixedEq('ep_ha_issue_00474f9e', $oldInterface['interfaces'][0]['identifier'], 'actual endpoint interface identity');
mixedEq(3990, $oldInterface['interfaces'][0]['tag'], 'actual endpoint VLAN tag');
$interfaceReceiver = mixedInterfaceReceiver($oldInterface['policies']);
$coreBefore = [
    'interfaces' => $interfaceReceiver['interfaces'],
    'vlans' => $interfaceReceiver['vlans']['vlan'],
    'core_assignments' => InterfaceSync::assignments($interfaceReceiver),
];
$prepare = $oldInterface;
$prepare['prune'] = false;
$prepared = InterfaceSync::reconcile(
    $interfaceReceiver, $prepare, mixedUuidFactory('new-rigi-prepared-')
);
mixedEq(true, $prepared['changed'], 'new Rigi applies old Etna v2 prepare');
$final = InterfaceSync::reconcile(
    $prepared['config'], $oldInterface,
    static fn() => throw new RuntimeException('finalize must retain created VLAN UUID')
);
$interfaceReceived = $final['config'];
mixedEq('endpoint',
    InterfaceSync::assignments($interfaceReceived)['ep_ha_issue_00474f9e']['policy_id'],
    'old Etna v2 target becomes normal Rigi interface assignment');
mixedEq(false,
    isset($interfaceReceived['OPNsense']['ApiExtensions']['InterfaceSyncPolicy']['replicas']),
    'no replica ownership state created on new Rigi');
mixedEq($coreBefore['interfaces']['core_wan'], $interfaceReceived['interfaces']['core_wan'],
    'new Rigi preserves local core WAN');
mixedEq($coreBefore['vlans'][0], $interfaceReceived['vlans']['vlan'][0],
    'new Rigi preserves local HA transit VLAN');
mixedEq($coreBefore['core_assignments']['core_wan']['@attributes'],
    InterfaceSync::assignments($interfaceReceived)['core_wan']['@attributes'],
    'new Rigi preserves core WAN policy assignment UUID');
mixedEq(
    InterfaceSync::validatePayload($oldInterface),
    InterfaceSync::validatePayload(InterfaceSync::buildPayload($interfaceReceived)),
    'new Rigi may immediately send semantically equivalent v2 payload'
);
$repeatInterface = InterfaceSync::reconcile(
    $interfaceReceived, $oldInterface,
    static fn() => throw new RuntimeException('repeat interface UUID factory must not run')
);
mixedEq(false, $repeatInterface['changed'], 'old v2 interface finalize repeat is idempotent');

// The NEXT leg is new Rigi -> freshly installed new Etna. Its target must
// rebuild normal assignments locally, with different UUIDs but the same
// semantic interface and policy ID. Neither router becomes an "owner".
$newRigiInterfaceV2 = InterfaceSync::buildPayload($interfaceReceived);
$newEtnaInterface = InterfaceSync::reconcile(
    mixedInterfaceReceiver($oldInterface['policies']),
    $newRigiInterfaceV2,
    mixedUuidFactory('fresh-etna-interface-')
);
$newEtnaInterfaceConfig = $newEtnaInterface['config'];
mixedEq(
    InterfaceSync::validatePayload($oldInterface),
    InterfaceSync::validatePayload(InterfaceSync::buildPayload($newEtnaInterfaceConfig)),
    'old Etna -> new Rigi -> new Etna conserves interface semantics'
);
mixedEq(false,
    InterfaceSync::assignments($newEtnaInterfaceConfig)['ep_ha_issue_00474f9e']['@attributes']['uuid']
        === InterfaceSync::assignments($interfaceReceived)['ep_ha_issue_00474f9e']['@attributes']['uuid'],
    'new Etna assigns independent local assignment UUID after fresh reinstall');
mixedEq(false,
    InterfaceSync::reconcile(
        $newEtnaInterfaceConfig, $newRigiInterfaceV2,
        static fn() => throw new RuntimeException('new Etna repeat must not generate UUID')
    )['changed'],
    'new Etna repeated reverse-selected sync is idempotent');

$oldHAProxy = $fixture['haproxy'];
mixedEq(2, $oldHAProxy['version'], 'old Etna HAProxy payload v2');
mixedEq(3, count($oldHAProxy['objects']), 'old Etna real HAProxy relation graph');
$haproxyReceiver = mixedHAProxyReceiver($oldHAProxy['policies']);
$localFrontend = $haproxyReceiver['OPNsense']['HAProxy']['frontends'];
$haproxyCreated = HAProxySync::reconcile(
    $haproxyReceiver, $oldHAProxy,
    mixedUuidFactory('new-rigi-haproxy-uuid-'),
    mixedUuidFactory('new-rigi-haproxy-id-')
);
mixedEq(true, $haproxyCreated['changed'], 'new Rigi accepts old Etna HAProxy v2 objects');
$newHaproxyConfig = $haproxyCreated['config'];
mixedEq($localFrontend, $newHaproxyConfig['OPNsense']['HAProxy']['frontends'],
    'new Rigi never overwrites local frontend');
mixedEq(3, count(HAProxySync::assignments($newHaproxyConfig)),
    'normal policy assignments created for healthcheck/server/backend');
mixedEq(
    HAProxySync::validatePayload($oldHAProxy),
    HAProxySync::validatePayload(HAProxySync::buildPayload($newHaproxyConfig)),
    'new Rigi regenerates same canonical v2 HAProxy object graph for reverse sync'
);
$repeatHaproxy = HAProxySync::reconcile(
    $newHaproxyConfig, $oldHAProxy,
    static fn() => throw new RuntimeException('repeat HAProxy UUID factory must not run'),
    static fn() => throw new RuntimeException('repeat HAProxy id factory must not run')
);
mixedEq(false, $repeatHaproxy['changed'], 'old Etna v2 HAProxy repeat is idempotent');

// Last leg: new Rigi sends its reconstructed HAProxy graph into fresh Etna.
// UUID-backed relations in the new receiver are rebuilt from stable NAMES.
$newRigiHaproxyV2 = HAProxySync::buildPayload($newHaproxyConfig);
$newEtnaHaproxy = HAProxySync::reconcile(
    mixedHAProxyReceiver($oldHAProxy['policies']),
    $newRigiHaproxyV2,
    mixedUuidFactory('fresh-etna-haproxy-uuid-'),
    mixedUuidFactory('fresh-etna-haproxy-id-')
);
mixedEq(3, count(HAProxySync::assignments($newEtnaHaproxy['config'])),
    'fresh Etna receives 3 normal HAProxy policy assignments');
mixedEq(
    HAProxySync::validatePayload($oldHAProxy),
    HAProxySync::validatePayload(HAProxySync::buildPayload($newEtnaHaproxy['config'])),
    'old Etna -> new Rigi -> new Etna conserves HAProxy semantics'
);
mixedEq(false,
    HAProxySync::assignments($newEtnaHaproxy['config'])['backend:sni-customer.example']['@attributes']['uuid']
        === HAProxySync::assignments($newHaproxyConfig)['backend:sni-customer.example']['@attributes']['uuid'],
    'fresh Etna generates an independent backend policy-assignment UUID');
mixedEq(false,
    HAProxySync::reconcile(
        $newEtnaHaproxy['config'], $newRigiHaproxyV2,
        static fn() => throw new RuntimeException('new Etna repeat UUID allocation'),
        static fn() => throw new RuntimeException('new Etna repeat local-id allocation')
    )['changed'],
    'new Etna repeated HAProxy sync is idempotent');

// Native receiver processes Interfaces and HAProxy in the SAME config.xml.
// Old Etna sources share a coherent policy table across both categories.
// The same receiver's interface assignments must survive HAProxy updates.
$combinedReceiver = $interfaceReceived;
$combinedReceiver['OPNsense']['HAProxy'] = $haproxyReceiver['OPNsense']['HAProxy'];
$combinedReceiver['OPNsense']['ApiExtensions']['InterfaceSyncPolicy']['haproxy_assignments'] = '';
$combinedResult = HAProxySync::reconcile(
    $combinedReceiver, $oldHAProxy,
    mixedUuidFactory('combined-rigi-ha-uuid-'),
    mixedUuidFactory('combined-rigi-ha-id-')
);
$combinedConfig = $combinedResult['config'];
mixedEq(true, isset(InterfaceSync::policies($combinedConfig)['services']),
    'HAProxy sync preserves local services HA policy from interface phase');
mixedEq('endpoint',
    InterfaceSync::assignments($combinedConfig)['ep_ha_issue_00474f9e']['policy_id'],
    'HAProxy sync preserves regular shared endpoint interface assignment');
mixedEq(
    InterfaceSync::validatePayload($oldInterface),
    InterfaceSync::validatePayload(InterfaceSync::buildPayload($combinedConfig)),
    'combined old interface and HAProxy payload preserves InterfaceSync semantics'
);
mixedEq(
    HAProxySync::validatePayload($oldHAProxy),
    HAProxySync::validatePayload(HAProxySync::buildPayload($combinedConfig)),
    'combined old interface and HAProxy payload preserves HAProxy semantics'
);

// Defensive mixed-version policy-subset case: an old peer may send a v2
// category payload that omits a node-local policy unused by that category.
// It may not delete local core/services policy definitions even if those
// definitions currently have zero assignments. Unused synchronized policies,
// in contrast, must remain authoritative prune candidates.
$partialOldHaproxy = $oldHAProxy;
$partialOldHaproxy['policies'] = array_values(array_filter(
    $oldHAProxy['policies'],
    fn($p) => $p['id'] !== 'services'
));
$partialReceiver = $combinedReceiver;
$partialReceiver['OPNsense']['ApiExtensions']['InterfaceSyncPolicy']['shared']['policies']['policy'][] = [
    '@attributes' => ['uuid' => 'receiver-obsolete-policy-uuid'],
    'id' => 'obsolete_sync',
    'description' => 'Unreferenced prior synchronized policy',
    'synchronize' => '1',
];
$partialResult = HAProxySync::reconcile(
    $partialReceiver, $partialOldHaproxy,
    mixedUuidFactory('partial-ha-uuid-'),
    mixedUuidFactory('partial-ha-id-')
);
$partialPolicies = InterfaceSync::policies($partialResult['config']);
mixedEq(true, isset($partialPolicies['services']), 'absent unassigned local services policy retained');
mixedEq(false, isset($partialPolicies['obsolete_sync']), 'absent unassigned synchronized policy pruned');
mixedEq(1, $partialResult['plan']['policies']['retained_local'], 'one local-only policy explicitly retained');
mixedEq('endpoint',
    InterfaceSync::assignments($partialResult['config'])['ep_ha_issue_00474f9e']['policy_id'],
    'policy subset must never break existing interface policy assignment');

echo "MIXED_VERSION_V2_PASS old_etna=7dc9649e new_rigi=current"
    . " vlan=3990 interface=ep_ha_issue_00474f9e haproxy=3"
    . " local_core_preserved=1 reverse_new_etna=1 repeat_idempotent=1\n";
